package com.smritisathi.app.reminders;
import android.app.*;import android.content.*;import android.os.*;import com.smritisathi.app.core.*;import com.google.gson.*;
public class ReminderReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){String action=i.getAction();String id=i.getStringExtra("reminderId");if("DONE".equals(action)||"SNOOZE".equals(action)){String status="DONE".equals(action)?"done":"snoozed";JsonObject b=new JsonObject();b.addProperty("status",status);if(id!=null)ApiClient.request("PATCH","/reminders/"+id+"/status",Session.token(c),b,(ok,d,e)->{});return;}String title=i.getStringExtra("title");Intent done=new Intent(c,ReminderReceiver.class);done.setAction("DONE");done.putExtra("reminderId",id);Intent snooze=new Intent(c,ReminderReceiver.class);snooze.setAction("SNOOZE");snooze.putExtra("reminderId",id);PendingIntent p1=PendingIntent.getBroadcast(c,(id+"d").hashCode(),done,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent p2=PendingIntent.getBroadcast(c,(id+"s").hashCode(),snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String ch="reminders";NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(ch,"Reminders",NotificationManager.IMPORTANCE_HIGH));Notification.Builder nb=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c);nb.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Medicine Time".equals(title)?"🔔 Medicine Time":"⏰ Reminder").setContentText(title).setAutoCancel(true).addAction(new Notification.Action.Builder(null,"Done ✓",p1).build()).addAction(new Notification.Action.Builder(null,"Remind Me Later",p2).build());nm.notify(id==null?1:id.hashCode(),nb.build());}}
